39	const PROCESSING_FEE = 5;
40	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
41	  sword: 100,
42	  amulet: 60,
43	  staff: 80,
44	  potion: 40,
45	  rune: 25,
46	  moonstone: 25,
47	};
48	const FIRST_INSURANCE_RATE = 0.1;
49	
50	const withFirstInsuranceSurcharge = (policyBase: number): number =>
51	  policyBase + policyBase * FIRST_INSURANCE_RATE;
52	
53	const COMPONENT_BLOCK_SIZE = 3;
54	const COMPONENT_BLOCK_PREMIUM = 60;
55	
56	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
57	
58	const formsComponentBlock = (items: Item[]): boolean =>
59	  items.length === COMPONENT_BLOCK_SIZE &&
60	  items.every((item) => item.type === "rune");
61	
62	const sumOfItemBasePremiums = (items: Item[]): number =>
63	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
64	
65	const policyBasePremium = (items: Item[]): number =>
66	  formsComponentBlock(items)
67	    ? COMPONENT_BLOCK_PREMIUM
68	    : sumOfItemBasePremiums(items);
69	
70	const quotePremium = (items: Item[]): number =>
71	  Math.ceil(withFirstInsuranceSurcharge(policyBasePremium(items)) + PROCESSING_FEE);
72	
73	const runStep = (step: Step): StepResult => {
74	  if (step.op === "quote") return { premium: quotePremium(step.items) };
75	  throw new Error(`unsupported step: ${step.op}`);
76	};
77	
78	export const runScenario = (scenario: Scenario): ScenarioResult => ({
79	  results: scenario.steps.map(runStep),
80	});
