// Deliberately additive: `policyBase * 1.1` is not float-equivalent
// (100 * 1.1 === 110.00000000000001), and the final rounding-up turns that
// stray ulp into a whole extra gold piece. Do not "simplify".
const withFirstInsuranceSurcharge = (policyBase: number): number =>
  policyBase + policyBase * FIRST_INSURANCE_RATE;

// The MHPCO rounds premiums in its own favour.
const roundedInMHPCOsFavour = (premium: number): number => Math.ceil(premium);

const quotePremium = (items: Item[]): number =>
  roundedInMHPCOsFavour(
    withFirstInsuranceSurcharge(policyBasePremium(items)) + PROCESSING_FEE,
  );
